cd /tmp && python3 << 'EOF'
import os, glob, zipfile
# only maxdepth 2 to be quick
files=[]
for root, dirs, fns in os.walk('/tmp'):
    # skip deep
    depth = root.count('/')
    if depth > 3:
        dirs[:] = []
        continue
    for fn in fns:
        if fn.endswith('.xlsx'):
            files.append(os.path.join(root, fn))
print('num xlsx shallow', len(files))
hits=[]
for f in files:
    try:
        z = zipfile.ZipFile(f)
        blob=b''
        for n in z.namelist():
            if 'sheet' in n or 'sharedStrings' in n:
                blob += z.read(n)
        text=blob.decode('utf-8','ignore')
        if 'Earrings' in text:
            hits.append(f)
        z.close()
    except Exception:
        pass
print('hits', len(hits))
for h in hits:
    print(h)
